def test_AC_extraction_result_envelope_1_rejects_unknown_versions_and_defaults():
    'AC-extraction.result-envelope.1'; payload = _complete_result().to_payload(); payload['schema_version'] = '999'
    with pytest.raises(ValueError, match='schema version'): StatementExtractionResult.from_payload(payload)
